from pathlib import Path
import json
from html import escape
root=Path(__file__).resolve().parents[1]
screens=json.loads((root/'design/screens.json').read_text(encoding='utf-8'))
cards=''.join(f'<a class="card" href="{escape(s["html"])}"><img loading="lazy" src="{escape(s["screenshot"])}" alt="{escape(s["title"])}"><h2>{escape(s["title"])}</h2><p>{escape(s["device"])} · Reviewed HTML concept ↗</p></a>' for s in screens)
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Momentum — Design gallery</title><style>body{margin:0;background:#0b1220;color:#f2f0ea;font:16px/1.6 system-ui;padding:40px}main{max-width:1400px;margin:auto}a{color:#55d6be}h1{font-size:48px;letter-spacing:-.04em;line-height:1.1}p{color:#a7b5c9}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:24px}.card{color:inherit;text-decoration:none;background:#162238;border:1px solid #2b3c54;border-radius:16px;padding:18px}.card img{width:100%;height:280px;object-fit:contain;object-position:top;background:#0b1220}.card h2{font-size:18px}.card p{font-size:13px}a:focus-visible{outline:3px solid #55d6be;outline-offset:4px}</style></head><body><main><a href="../web/index.html">← Open local calculators & reference libraries</a><h1>Momentum.<br>A routine with a way back.</h1><p>Six desktop and four iPhone concepts created in Google Stitch. Synthetic data; static controls. Native apps, HealthKit and cloud sync are not implemented.</p><p><a href="https://stitch.withgoogle.com/projects/6081622018842562931">Open private Stitch project ↗</a> · Use the connected Google account.</p><div class="grid">'''+cards+'''</div><p>All sample food values and workout loads in these concepts are illustrative. See the separate sourced reference datasets for actual collected records.</p></main></body></html>'''
(root/'design/index.html').write_text(html,encoding='utf-8')
print('Gallery generated for',len(screens),'reviewed concepts.')
